-- Driver for tests/test_lua_history.py (Lua plan item 6): runs the Lua accounting/reliability/history writers on
-- scenarios generated by Python and writes what they produced, so Python can compare it with agent.Accounting,
-- reliability.Reliability, route_history, latency_history, stats_reset and native_history on the same inputs.
-- Usage: TZ=... lua5.1 history_differential.lua <cases.json> <results.json>
local here=(arg[0]:match('^(.*)/[^/]*$') or '.')
package.path=here..'/../../files/usr/lib/homensai-vpn/lua/?.lua;'..package.path
local canon=require('canon')
canon.configure({runtime=os.getenv('HOMENSAI_TEST_RUNTIME') or '/tmp'})
local accounting=require('accounting')
local reliability=require('reliability')

local function read(path) local f=io.open(path,'rb');if not f then return nil end;local s=f:read('*a');f:close();return s end
local function write(path,s) local f=assert(io.open(path,'wb'));f:write(s);f:close() end
local N=canon.number

-- A runner on real files (checkpoint/restore cases) with a fixed wall clock.
local function file_runner(clock)
  local R={RUNTIME=clock.runtime,PERSIST=clock.persist}
  function R.wall() return clock.now end
  function R.clock() return clock.now end
  R.read_file=read
  function R.write_atomic(path,text)
    local directory=string.match(path,'^(.*)/[^/]+$')
    if not io.open(directory..'/.probe','wb') then os.execute('mkdir -p "'..directory..'"') else os.remove(directory..'/.probe') end
    write(path,text)
  end
  R.write_ram=R.write_atomic
  function R.file_size(path) local f=io.open(path,'rb');if not f then return nil end;local n=f:seek('end');f:close();return n end
  function R.exists(path) return R.file_size(path)~=nil end
  function R.remove(path) os.remove(path) end
  function R.list_dir(path)
    local p=io.popen('ls -1 "'..path..'" 2>/dev/null');local out={}
    for line in p:lines() do out[#out+1]=line end;p:close();return out
  end
  function R.try_lock(_,fn) return true,fn() end
  return R
end

local function apply(acc,op)
  local kind=op.op
  if kind=='sample' then acc:sample(op.device,op.ifindex,op.rx,op.tx,op.now,op.max_gap)
  elseif kind=='wan_sample' then
    if acc.wan==nil then acc.wan=accounting.new() end
    acc.wan:sample(op.device,op.ifindex,op.rx,op.tx,op.now,op.max_gap)
  elseif kind=='note_gap' then acc.gaps=acc.gaps+1;acc:note_gap(op.start,op['end'])
  elseif kind=='track' then acc:track_activity(op.rows,op.now,op.max_gap)
  elseif kind=='observe' then
    local native=op.native;if native==canon.null then native=nil end
    acc:observe(op.row,op.max_gap,native,op.pair)
  elseif kind=='retention' then acc:apply_detail_retention(op.days,op.now)
  elseif kind=='controller' then acc.reliability:controller(op.active,op.now,op.max_gap)
  elseif kind=='route' then
    local okr,route=pcall(reliability.observed_route,op.status,op.now)
    route=okr and route or 'unknown'
    local changed=acc.reliability.routes:observe(route,op.now,op.max_gap)
    return canon.array({route,changed})
  elseif kind=='compact' then acc:compact(op.limit)
  elseif kind=='export' then return canon.encode(acc:export())
  elseif kind=='public' then return canon.encode(acc:public_export(op.now))
  elseif kind=='reliability_public' then return canon.encode(acc.reliability:public())
  else error('unknown op '..tostring(kind)) end
  return canon.null
end

local cases=canon.decode(read(arg[1]))
local results=canon.object()

-- accounting scenarios: {initial=data|null, ops=[...]} -> outputs of every op (+ error text)
if cases.accounting then
  local out=canon.array()
  for _,case in ipairs(cases.accounting) do
    local acc=accounting.new(case.initial~=canon.null and case.initial or nil)
    local outputs=canon.array()
    local ok,err=pcall(function() for _,op in ipairs(case.ops) do outputs[#outputs+1]=apply(acc,op) end end)
    out[#out+1]=canon.object({outputs=outputs,error=ok and canon.null or tostring(err)})
  end
  results.accounting=out
end

-- reliability constructor validation: {data, detail_days} -> code or the canonical export
if cases.reliability_validate then
  local out=canon.array()
  for _,case in ipairs(cases.reliability_validate) do
    local ok,value=pcall(reliability.new,case.data,case.detail_days)
    out[#out+1]=ok and canon.encode(value:export()) or ('error:'..tostring(value))
  end
  results.reliability_validate=out
end

-- observed_route / active_controller on statuses
if cases.routes then
  local out=canon.array()
  for _,case in ipairs(cases.routes) do
    local ok,value=pcall(reliability.observed_route,case.status,case.now)
    out[#out+1]=ok and value or 'error'
  end
  results.routes=out
end
if cases.controllers then
  local out=canon.array()
  for _,case in ipairs(cases.controllers) do out[#out+1]=reliability.active_controller(case.native,case.state,case.intent,case.now) end
  results.controllers=out
end

-- checkpoint: Lua writes checkpoint.json(+backup) in a directory from an accounting scenario; restore: Lua reads
-- a directory (written by Python) and exports what it restored.
if cases.checkpoints then
  local out=canon.array()
  for _,case in ipairs(cases.checkpoints) do
    local clock={now=N(case.now),persist=case.directory,runtime=case.directory}
    local R=file_runner(clock)
    local row=canon.object()
    if case.action=='restore' then
      local acc,notice=accounting.restore(R,case.directory)
      row.export=canon.encode(acc:export());row.notice=notice or canon.null
    else  -- stages: [{ops, now}]: apply the ops, then checkpoint at now (the second one rotates the backup)
      local acc=accounting.new(case.initial~=canon.null and case.initial or nil)
      local exports=canon.array()
      for _,stage in ipairs(case.stages) do
        for _,op in ipairs(stage.ops) do apply(acc,op) end
        clock.now=N(stage.now)
        accounting.checkpoint(R,case.directory,acc)
        exports[#exports+1]=canon.encode(acc:export())
      end
      row.exports=exports
    end
    out[#out+1]=row
  end
  results.checkpoints=out
end

-- extra drivers registered by other modules (latency history, stats reset, ...)
local extra=dofile(here..'/history_differential_extra.lua')
extra(cases,results,{canon=canon,read=read,write=write,file_runner=file_runner})

write(arg[2],canon.encode(results))
